// ANCHOR: example
//! `bolero` is a fuzzing frontend for Rust that supports multiple engines
//! like libFuzzer, AFL, and Honggfuzz. It also allows running fuzz targets
//! as regular unit tests.

use bolero::check;

/// Reports whether the data starts with the example's six-byte marker.
fn process_data(data: &[u8]) -> bool {
    data.starts_with(b"bolero")
}

/// Feeds the data generated by `bolero` to [`process_data`].
fn main() {
    // This will run the fuzzer when executed with `cargo bolero fuzz`
    // or as a regular test with `cargo test`.
    check!().for_each(|data| {
        let _has_marker = process_data(data);
    });
}
// ANCHOR_END: example

/// Runs the Bolero fuzz example.
pub fn run() {
    main();
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    /// Runs the generated-input loop with Bolero's default test iterations.
    fn test_bolero() {
        // When running as a test, it uses a default number of iterations.
        main();
    }

    #[test]
    /// Detects the marker while safely rejecting short or unrelated inputs.
    fn process_data_recognizes_only_the_marker_prefix() {
        assert!(!process_data(b""));
        assert!(!process_data(b"bol"));
        assert!(process_data(b"bolero"));
        assert!(process_data(b"bolerox"));
        assert!(!process_data(&[0xff; 1024]));
    }
}
